package com.masona.pocketledger;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.os.*;import android.provider.Settings;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.*;import org.json.*;
public class MainActivity extends Activity {
 private LinearLayout root;private final int ink=Color.rgb(241,244,248),muted=Color.rgb(148,162,184),amber=Color.rgb(242,187,115);private boolean dashboard=false;private int historyDays=90;
 private android.content.SharedPreferences prefs(){return getSharedPreferences("ledger",0);}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);SyncJob.schedule(this);home();}
 public void onResume(){super.onResume();if(!dashboard)home();}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(7),0,dp(9));root.addView(t);return t;}
 void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextColor(Color.rgb(40,31,20));b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(amber));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(9),0,dp(6));root.addView(b,p);b.setOnClickListener(v->action.run());}
 void home(){dashboard=false;ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(12,19,32));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(25),dp(42),dp(25),dp(35));scroll.addView(root);setContentView(scroll);
  text("↗  POCKET LEDGER",18,amber);text("Money, with clarity.",32,ink);text("Your phone captures. Your ledger makes sense of it.",14,muted);
  boolean paired=false;int pending=0,rejected=0;try(Vault v=new Vault(this)){paired=v.token()!=null;pending=v.count("pending");rejected=v.count("rejected");}catch(Exception e){text("Encrypted storage unavailable. Re-pair or check your device storage.",12,amber);}
  text((paired?"✓ Paired with your private ledger":"1. Pair your phone")+"\n"+pending+" messages waiting to sync"+(rejected>0?"\n"+rejected+" messages need manual attention":""),15,ink);
  text(prefs().getString("sync_status","Your first sync will appear here."),12,muted);
  button(paired?"Re-pair with my ledger":"Pair with my ledger",this::pair);
  text("2. Choose your notification sources",18,ink);text("Select your SMS app and any banking or mobile-money apps that send transaction notifications. Sender filters prevent unrelated messages from being collected.",12,muted);
  button("Choose apps ("+prefs().getStringSet("sources",Collections.emptySet()).size()+" selected)",this::sources);
  button("Sender filters: "+prefs().getString("senders","MTN,Airtel,FNB,MoMo"),this::senders);
  text("3. Enable notification access",18,ink);String listeners=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");boolean enabled=listeners!=null&&listeners.contains(getPackageName()+"/");text(enabled?"✓ Android notification access enabled":"Android notification access is not enabled yet.",12,enabled?amber:muted);
  button("Open notification access settings",()->startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)));
  text("If Android blocks this setting after APK installation: open Settings → Apps → Pocket Ledger → the three-dot menu → Allow restricted settings. Then return here. Device menus may differ.",12,muted);
  Switch capture=new Switch(this);capture.setText("Capture transaction notifications");capture.setTextColor(ink);capture.setChecked(prefs().getBoolean("capture",false));capture.setPadding(0,dp(15),0,dp(15));root.addView(capture);capture.setOnCheckedChangeListener((b,on)->{if(on&&prefs().getStringSet("sources",Collections.emptySet()).isEmpty()){capture.setChecked(false);Toast.makeText(this,"Choose at least one source app first.",Toast.LENGTH_LONG).show();return;}prefs().edit().putBoolean("capture",on).apply();});
  text(prefs().getString("capture_status","Notification capture starts after you enable it. Use the optional history importer for older SMS."),12,muted);
  button("Sync now",()->{SyncJob.kick(this);Toast.makeText(this,"Checking connection. Messages stay saved until confirmed.",Toast.LENGTH_LONG).show();new Handler(getMainLooper()).postDelayed(()->{if(!dashboard)home();},1800);});
  button("Open my spending dashboard",this::web);
  button("View offline queue",this::queue);
  button("Import previous transaction SMS",this::importHistory);
  text(prefs().getString("history_status","History import is optional: preview matches before saving. No messages are changed or deleted in your SMS app."),12,muted);
  text("Only transaction-like messages from your selected sources are captured. OTPs and login codes are skipped. Messages are encrypted on your phone and sent over HTTPS to your server, never to external AI. Android can delay background sync or hide message content; paste missing messages in the dashboard.",12,muted);
  if(paired)button("Disconnect this phone",()->new AlertDialog.Builder(this).setMessage("This removes the phone credential and stops capture. Queued messages stay encrypted locally. Revoke the device in the web dashboard to invalidate server access.").setPositiveButton("Disconnect",(d,w)->{try(Vault v=new Vault(this)){v.forget();}home();}).setNegativeButton("Cancel",null).show());
 }
 private void importHistory(){
  new AlertDialog.Builder(this).setTitle("Import your previous transaction SMS")
   .setMessage("Pocket Ledger needs SMS read access to scan your phone's inbox for this one-time import. It reads the date, sender and text locally, keeps only transaction-like messages matching your sender filters, and skips OTP/login codes. You will preview the matches and choose which ones to save. Only your selected messages enter the encrypted queue and sync to your paired private server. It does not change, delete or send SMS, and cannot recover old banking-app notifications. You can remove SMS permission afterward in Android app settings.")
   .setPositiveButton("Choose date range",(d,w)->new AlertDialog.Builder(this).setTitle("How far back?").setItems(new String[]{"Last 30 days","Last 90 days","Last year","All SMS still on this phone"},(range,index)->{historyDays=new int[]{30,90,365,0}[index];if(checkSelfPermission(android.Manifest.permission.READ_SMS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.READ_SMS},4201);else scanHistory();}).setNegativeButton("Cancel",null).show())
   .setNegativeButton("Cancel",null).show();
 }
 public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){
  super.onRequestPermissionsResult(requestCode,permissions,results);
  if(requestCode==4201){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)scanHistory();else new AlertDialog.Builder(this).setTitle("SMS permission was not granted").setMessage("No history was imported. Notification capture still works independently. You can allow SMS in Settings → Apps → Pocket Ledger → Permissions. If Android's installer restricts this permission, use the developer-installed build or paste messages in the web dashboard.").setPositiveButton("Close",null).show();}
 }
 private void scanHistory(){
  final int days=historyDays;final String keywords=prefs().getString("senders","MTN,Airtel,FNB,MoMo");
  final AlertDialog progress=new AlertDialog.Builder(this).setTitle("Checking your SMS history").setMessage("Finding transaction-like messages locally. Nothing is being uploaded.").setCancelable(false).create();progress.show();
  new Thread(()->{try{SmsHistory.Result result=SmsHistory.scan(this,days,keywords);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;progress.dismiss();previewHistory(result);});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;progress.dismiss();new AlertDialog.Builder(this).setTitle("Unable to read SMS history").setMessage("No messages were imported. Check Pocket Ledger's SMS permission in Android settings. Notification capture is unaffected.").setPositiveButton("Close",null).show();});}}).start();
 }
 private void previewHistory(SmsHistory.Result result){
  if(result.events.isEmpty()){new AlertDialog.Builder(this).setTitle("No new matching SMS").setMessage("Checked "+result.scanned+" messages. "+result.alreadySaved+" matches were already saved. Check Sender filters if your bank uses a short code or different sender name. This scan covers SMS only, not RCS chats, MMS or old app notifications."+(result.limited?" The scan reached its safety limit; try a smaller date range.":"")).setPositiveButton("Close",null).show();return;}
  String[] labels=new String[result.events.size()];boolean[] selected=new boolean[labels.length];java.text.DateFormat dates=java.text.DateFormat.getDateInstance();
  for(int i=0;i<labels.length;i++){JSONObject event=result.events.get(i);labels[i]=dates.format(new java.util.Date(event.optLong("occurred")))+" · "+event.optString("sender")+"\n"+event.optString("text");selected[i]=true;}
  new AlertDialog.Builder(this).setTitle("Preview "+labels.length+" transaction messages"+(result.limited?" (batch limit)":""))
   .setMultiChoiceItems(labels,selected,(d,index,on)->selected[index]=on)
   .setPositiveButton("Import selected",(d,w)->{List<JSONObject> chosen=new ArrayList<>();for(int i=0;i<selected.length;i++)if(selected[i])chosen.add(result.events.get(i));if(chosen.isEmpty()){Toast.makeText(this,"Nothing selected. No messages saved.",Toast.LENGTH_LONG).show();return;}final AlertDialog saving=new AlertDialog.Builder(this).setTitle("Saving selected messages").setMessage("Encrypting the import on your phone.").setCancelable(false).create();saving.show();new Thread(()->{try{int count;try(Vault vault=new Vault(this)){count=vault.addHistory(chosen);}prefs().edit().putString("history_status",count+" historical SMS saved for review. "+(result.limited?"Run import again for the next batch. ":"")+"Open your web dashboard and choose their original month.").apply();SyncJob.schedule(this);SyncJob.kick(this);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;saving.dismiss();home();Toast.makeText(this,count+" messages queued securely. They will appear in Review after sync.",Toast.LENGTH_LONG).show();});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;saving.dismiss();Toast.makeText(this,"Import could not be saved. No partial batch was added.",Toast.LENGTH_LONG).show();});}}).start();})
   .setNegativeButton("Cancel",null).show();
 }
 private void pair(){EditText code=new EditText(this);code.setHint("Paste the one-time pairing code");code.setSingleLine(true);code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);new AlertDialog.Builder(this).setTitle("Pair with your ledger").setMessage("On the website, open Phone → Pair phone. Paste its private code here. Server: "+SyncJob.ORIGIN).setView(code).setPositiveButton("Pair",(d,w)->{String value=code.getText().toString().trim();if(!value.matches("[a-f0-9]{64}")){Toast.makeText(this,"Use the full code from your web dashboard.",Toast.LENGTH_LONG).show();return;}new Thread(()->{try{JSONObject result=SyncJob.request("/device/pair",new JSONObject().put("code",value).put("name",Build.MANUFACTURER+" "+Build.MODEL),null);try(Vault v=new Vault(this)){v.storeToken(result.getString("token"));}runOnUiThread(()->{home();Toast.makeText(this,"Phone paired. Choose your sources next.",Toast.LENGTH_LONG).show();});SyncJob.kick(this);}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Pairing failed: "+e.getMessage(),Toast.LENGTH_LONG).show());}}).start();}).setNegativeButton("Cancel",null).show();}
 private void sources(){PackageManager pm=getPackageManager();List<ResolveInfo> resolved=pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);TreeMap<String,String> apps=new TreeMap<>();for(ResolveInfo r:resolved)if(!r.activityInfo.packageName.equals(getPackageName()))apps.put(r.loadLabel(pm)+" · "+r.activityInfo.packageName,r.activityInfo.packageName);String[] labels=apps.keySet().toArray(new String[0]);Set<String> selected=new HashSet<>(prefs().getStringSet("sources",Collections.emptySet()));boolean[] checked=new boolean[labels.length];for(int i=0;i<labels.length;i++)checked[i]=selected.contains(apps.get(labels[i]));new AlertDialog.Builder(this).setTitle("Transaction notification apps").setMultiChoiceItems(labels,checked,(d,i,on)->{if(on)selected.add(apps.get(labels[i]));else selected.remove(apps.get(labels[i]));}).setPositiveButton("Save",(d,w)->{prefs().edit().putStringSet("sources",selected).apply();home();}).setNegativeButton("Cancel",null).show();}
 private void senders(){EditText field=new EditText(this);field.setText(prefs().getString("senders","MTN,Airtel,FNB,MoMo"));new AlertDialog.Builder(this).setTitle("Allowed sender keywords").setMessage("Comma-separated sender names or bank app identifiers. Only matching transaction-like notifications are stored. Add a short code if your bank uses one. Example: MTN,Airtel,FNB,MoMo").setView(field).setPositiveButton("Save",(d,w)->{String v=field.getText().toString().trim();if(v.isEmpty()||v.length()>500){Toast.makeText(this,"Enter at least one keyword, under 500 characters.",Toast.LENGTH_LONG).show();return;}prefs().edit().putString("senders",v).apply();home();}).setNegativeButton("Cancel",null).show();}
 private void queue(){try(Vault v=new Vault(this)){JSONArray rows=v.pending();StringBuilder s=new StringBuilder();for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i);s.append(e.optString("sender")).append("\n").append(e.optString("text")).append("\n\n");}new AlertDialog.Builder(this).setTitle("Encrypted offline queue").setMessage(s.length()>0?s.toString():"No pending messages. Synced message bodies are removed from phone storage.").setPositiveButton("Close",null).show();}catch(Exception e){Toast.makeText(this,"Unable to read the encrypted queue.",Toast.LENGTH_LONG).show();}}
 private void web(){dashboard=true;LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(0,dp(28),0,0);layout.setBackgroundColor(Color.rgb(12,19,32));Button back=new Button(this);back.setText("← Capture settings");back.setOnClickListener(v->home());layout.addView(back);WebView web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){String url=req.getUrl().toString();if(url.equals(SyncJob.ORIGIN)||url.startsWith(SyncJob.ORIGIN+"/"))return false;return true;}public void onReceivedError(WebView view,WebResourceRequest req,WebResourceError err){if(req.isForMainFrame())Toast.makeText(MainActivity.this,"Dashboard needs an internet connection. Offline captures remain saved.",Toast.LENGTH_LONG).show();}});layout.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);web.loadUrl(SyncJob.ORIGIN);}
 public void onBackPressed(){if(dashboard)home();else super.onBackPressed();}
}
